use dg_xch_core::clvm::program::{Program, SerializedProgram};
use lazy_static::lazy_static;
use dg_xch_core::blockchain::sized_bytes::Bytes32;

const NFT_OWNERSHIP_LAYER_HEX: &str = "";
const NFT_STATE_LAYER_HEX: &str = "";

lazy_static! {
    pub static ref NFT_OWNERSHIP_LAYER: Program = SerializedProgram::from_hex(NFT_OWNERSHIP_LAYER_HEX)
        .unwrap()
        .to_program();
    pub static ref NFT_STATE_LAYER: Program = SerializedProgram::from_hex(NFT_STATE_LAYER_HEX)
        .unwrap()
        .to_program();
    pub static ref NFT_OWNERSHIP_LAYER_HASH: Bytes32 = NFT_OWNERSHIP_LAYER.tree_hash();
    pub static ref NFT_STATE_LAYER_HASH: Bytes32 = NFT_STATE_LAYER.tree_hash();
}
